<?php
/**
 * ChatHelp — apply-siteicon-v3 (CH_SITEICON_V3) — sitenin/PWA'nin ikonunu
 *  KOYU ANTRASIT + altin CH balonu (kullanicinin onayladigi v3) yapar.
 *   [1] Gomulu 512 PNG'yi diske yazar: icon-512-v3.png + GD ile 16/32/64/180/192.
 *   [2] Mevcut TUM eski ikon adlarini (legacy + -v2) v3 ile UZERINE yazar ->
 *       hicbir link kirilmaz, her yerde ayni ikon.
 *   [3] manifest.json ikon yollarini -v3'e yoneltir (yuklu PWA yenileyince yeni ikon).
 *   [4] index.php favicon/apple-touch link'lerine ?a3 cache-bust ekler.
 *  Lint + opcache reset. Additive/idempotent (manifest -v3 varsa cikar).
 * KULLANIM: pull2.php?key=...&files=apply-siteicon-v3.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
echo "apply-siteicon-v3 BASLADI OK (PHP ".PHP_VERSION.")\n\n";

$D = __DIR__;
$mf = "$D/manifest.json";
$mcur = @file_get_contents($mf);
if ($mcur!==false && strpos($mcur,'icon-512-v3.png')!==false) { echo "Zaten -v3 (guncel). Cikiliyor.\n"; exit; }

$b64 = <<<'B64'

B64;
$png = base64_decode($b64);
if ($png===false || strlen($png)<5000) { echo "✗ PNG decode hatasi\n"; exit; }

/* ── [1] 512 -> icon-512-v3.png ── */
$w = @file_put_contents("$D/icon-512-v3.png", $png);
echo ($w!==false && $w>5000) ? "  ✓ icon-512-v3.png yazildi ($w B)\n" : "  ✗ icon-512-v3.png YAZILAMADI\n";

/* GD ile diger boyutlar */
$sizes = array(16,32,64,180,192);
$src = function_exists('imagecreatefromstring') ? @imagecreatefromstring($png) : false;
$made = array();
if ($src) {
  foreach ($sizes as $sz) {
    $sm = function_exists('imagescale') ? @imagescale($src, $sz, $sz) : false;
    if ($sm) {
      @imagealphablending($sm,false); @imagesavealpha($sm,true);
      if (@imagepng($sm, "$D/icon-$sz-v3.png")) { $made[$sz]=true; }
      @imagedestroy($sm);
    }
  }
  @imagedestroy($src);
}
foreach ($sizes as $sz) {
  if (empty($made[$sz])) { @file_put_contents("$D/icon-$sz-v3.png", $png); }
}
echo "  ✓ v3 boyutlari: ".implode('/', $sizes)." (".(count($made))." GD, kalan kopya)\n";

/* ── [2] eski adlari (legacy + -v2) v3 ile uzerine yaz ── */
$overwrite = array(
  'icon-16.png'=>16, 'icon-32.png'=>32, 'icon-64.png'=>64, 'icon-180.png'=>180,
  'icon-192.png'=>192, 'icon-512.png'=>512,
  'icon-192-v2.png'=>192, 'icon-512-v2.png'=>512, 'apple-touch-icon.png'=>180,
);
$oc=0;
foreach ($overwrite as $name=>$sz) {
  $srcf = ($sz>=512) ? "$D/icon-512-v3.png" : "$D/icon-$sz-v3.png";
  if (!file_exists($srcf)) $srcf = "$D/icon-512-v3.png";
  if (@copy($srcf, "$D/$name")) $oc++;
}
echo "  ✓ $oc eski ikon adi v3 ile guncellendi (legacy + -v2 + apple-touch)\n";

/* ── [3] manifest.json -> -v3 ── */
if ($mcur===false) { echo "  ! manifest.json okunamadi (atlandi)\n"; }
else {
  $m = $mcur;
  $m = preg_replace('/icon-512(-v2)?\.png/','icon-512-v3.png',$m);
  $m = preg_replace('/icon-192(-v2)?\.png/','icon-192-v3.png',$m);
  json_decode($m);
  if (json_last_error()!==JSON_ERROR_NONE) { echo "  ✗ manifest JSON bozulacakti — DEGISTIRILMEDI\n"; }
  else if ($m===$mcur) { echo "  = manifest.json degismedi (zaten uygun)\n"; }
  else {
    @file_put_contents("$D/manifest.json.bak-siteicon-".date('Ymd-His'), $mcur);
    @file_put_contents($mf, $m);
    echo "  ✓ manifest.json ikon yollari -> -v3\n";
  }
}

/* ── [4] index.php favicon/apple-touch cache-bust (?a3) ── */
$idx = "$D/index.php"; $is = @file_get_contents($idx);
if ($is!==false) {
  $n=0;
  $is2 = preg_replace('/(icon-(?:16|32|64|180|192|512)(?:-v[0-9])?\.png)(\?[a-zA-Z0-9]+)?/','$1?a3',$is,-1,$n);
  $is2 = preg_replace('/(apple-touch-icon\.png)(\?[a-zA-Z0-9]+)?/','$1?a3',$is2);
  if ($is2!==$is && $is2!==null) {
    @file_put_contents("$idx.bak-siteicon-".date('Ymd-His'), $is);
    @file_put_contents($idx, $is2);
    echo "  ✓ index.php favicon link'lerine ?a3 cache-bust eklendi ($n)\n";
  } else {
    echo "  = index.php favicon link'i bulunamadi/degismedi (manifest yeter)\n";
  }
}

if (function_exists('opcache_reset')) @opcache_reset();
echo "\n✓ Site ikonu KOYU ANTRASIT v3 yapildi.\n";
echo "  Tarayici: sekme ikonu birkac dk icinde; PWA: app'i kapat-ac -> yeni ikon.\n";
echo "  Google Play: sana verdigim 512 PNG'yi ayrica Play Console'a yukle.\n";
